window.AUTH=window.AUTH||{};window.AUTH["19-840"]={"d":"19-840","id":"2020/19-840","n":"California v. Texas","briefs":[{"k":"respondent","label":"Brief of respondent U.S. House of Representatives in support of California, et al.","date":"2020-05-06","url":"https://www.supremecourt.gov/DocketPDF/19/19-840/142997/20200506130608104_19-840%20-%20House%20Opening%20Brief.pdf","side":"res","n":59},{"k":"petitioner","label":"Brief of petitioners California, et al.","date":"2020-05-06","url":"https://www.supremecourt.gov/DocketPDF/19/19-840/142986/20200506123245803_California%20v.%20Texas%20-%20No.%2019-840%20-%20Opening%20Brief%20for%20the%20Petitioners%20FINAL%20PDF-A%20FOR%20FILING.pdf","side":"pet","n":15}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r49_c0nd.pdf","tr":true,"items":[{"t":"case","label":"FEDERAL CASES Alaska Airlines, Inc. v. Brock","cite":"480 U.S. 678","y":1987,"id":"1986/85-920","sc":1,"op":4,"sum":"Section 43(f)(3)'s legislative-veto provision is severable from the remainder of the EPP program.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"op":9,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Amnesty Int’l USA v. Clapper","cite":"638 F.3d 118","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/638/118/","by":{"0":"21"}},{"t":"case","label":"Ayotte v. Planned Parenthood of N. New England","cite":"546 U.S. 320","y":2006,"id":"2005/04-1144","sc":1,"sum":"In a rare unanimous decision regarding abortion, the Supreme Court sidestepped the most contentious questions of the case and focused instead on the proper remedy when a portion of a statute is found unconstitutional.","sumSrc":"Oyez","by":{"0":"4, 32, 38, 40"}},{"t":"case","label":"Babbitt v. United Farm Workers Nat’l Union","cite":"442 U.S. 289","y":1979,"id":"1978/78-225","sc":1,"op":1,"sum":"Appellees (a farmworkers' union, a union agent, farmworkers, and a union supporter) brought suit in Federal District Court in Arizona seeking a declaration of the unconstitutionality of various provisions of Arizona's farm labor statute, as well as of the entire statute, and an injunction against \"its enforcement. A three-judge court ruled unconstitutional on various grounds the provisions (1) specifying procedures …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Bauer v. Marmara","cite":"774 F.3d 1026","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/774/1026/","by":{"0":"22"}},{"t":"case","label":"Bolivarian Republic of Venezuela v. Helmerich & Payne Int’l Drilling Co.","cite":"137 S. Ct. 1312","y":2017,"id":"2016/15-423","sc":1,"sum":"The Court determined that the “frivolous or insubstantial” standard is not consistent with the text and purpose of the Foreign Sovereign Immunities Act (FSIA)","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"sum":"The Court held that the Military Commissions Act of 2006 violated the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Clapper v. Amnesty Int’l USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"op":4,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"DaimlerChrysler Corp. v. Cuno","cite":"547 U.S. 332","y":2006,"id":"2005/04-1704","sc":1,"op":4,"ar":1,"sum":"The Supreme Court did not reach the central question presented, finding instead that Cuno and the other plaintiffs did not have standing to bring the suit. Chief Justice John Roberts, for the unanimous Court, wrote that simply alleging standing based on their status as taxpayers in Ohio and Michigan did not give them a sufficiently strong interest in the case.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Davis v. FEC","cite":"554 U.S. 724","y":2008,"id":"2007/07-320","sc":1,"sum":"Although all nine Justices agreed that Davis had standing to argue his case before the Court, only a 5-4 majority held that the contribution limits violated the First Amendment. In his majority opinion, Justice Samuel Alito noted that the Court had never upheld the constitutionality of a law imposing different contribution limits for candidates competing against one another.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Department of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30"}},{"t":"case","label":"Dimmitt v. City of Clearwater","cite":"985 F.2d 1565","y":1993,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/985/1565/","by":{"0":"36"}},{"t":"case","label":"Free Enter. Fund v. Pub. Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":2,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"40, 46"}},{"t":"case","label":"Gonzales v. Carhart","cite":"550 U.S. 124","y":2007,"id":"2006/05-380","sc":1,"sum":"The Court held that the Partial-Birth Abortion Ban Act did not violate a mother's personal liberty guaranteed under the Fifth Amendment.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"ar":2,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"King v. Burwell","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"op":2,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"2, 11, 49"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Lexmark Int’l, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":9,"ar":4,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"26, 29"}},{"t":"case","label":"Maine Community Health Options v. United States","cite":"2020 WL 1978706","y":2020,"court":"U.S. Apr. 27","op":3,"by":{"0":"4"}},{"t":"case","label":"Murphy v. NCAA","cite":"138 S. Ct. 1461","y":2018,"id":"2017/16-476","sc":1,"sum":"The Court decided that provisions of the Professional and Amateur Sports Protection Act (PASPA) that prohibit state authorization and licensing of sports gambling schemes violate the Constitution’s anticommandeering rule, and that no other PASPA provisions are severable from the provisions at issue.","sumSrc":"Oyez","by":{"0":"38, 39, 46"}},{"t":"case","label":"National Organization for Women, Inc. v. Scheidler","cite":"510 U.S. 249","y":1994,"id":"1993/92-780","sc":1,"op":1,"sum":"The unanimous Court held that organizations without an economic motive can detrimentally \"affect interstate or foreign commerce,\" satisfying the RICO definition of a racketeering enterprise. An \"enterprise\" does not have to be an economic organization or a principally criminal organization to trigger the RICO act. Consequently, the Court reversed the appeals court decision which allowed the original case to proceed.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"National Federation of Independent Business v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"op":15,"sum":"Describing other statutory provisions declaring that the individual mandate works “together” with the rest of the ACA.","sumSrc":"opinion","by":{"0":"passim"}},{"t":"case","label":"New York v. Dep’t of Commerce","cite":"351 F. Supp. 3d 502","y":2019,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/351/502/","by":{"0":"30"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"op":2,"sum":"The Court upheld two of the three provisions of the Act under review, reasoning that Congress had the authority under the Commerce Clause to use financial rewards and access to disposal sites as incentives for state waste management.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Papasan v. Allain","cite":"478 U.S. 265","y":1986,"id":"1985/85-499","sc":1,"sum":"Federal school land grants to Mississippi in the early 19th century did not apply to lands in northern Mississippi that were held by the Chickasaw Indian Nation, an area that came to be the northern 23 counties in the State. The Chickasaws thereafter ceded this area to the United States by a treaty under which the lands were sold, but no lands for public schools (Sixteenth Section lands) were reserved from sale. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Poe v. Ullman","cite":"367 U.S. 497","y":1961,"id":"1960/60","sc":1,"op":1,"sum":"The Court held that the ripeness doctrine prevents bringing claims to challenge criminal statutes that are not enforced.","sumSrc":"Oyez","by":{"0":"24, 25"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"op":7,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"sum":"The Court held that the case presented an actual controversy, as the Georgia statute could interfere with Steffel’s exercise of his constitutional rights even if he was not arrested. Because the United States’ involvement in Vietnam, which Steffel was protesting, was reduced, the issue of whether or not the case still presented an active controversy would be decided by the lower court on remand.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Grp. Brands LLC","cite":"137 S. Ct. 1514","y":2017,"id":"2016/16-341","sc":1,"sum":"The Court held that the subsection of the general venue statute that allows a corporation to reside in many jurisdictions for the purpose of establishing jurisdiction does not apply to the patent venue statute.","sumSrc":"Oyez","by":{"0":"15, 16"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"39, 46"}},{"t":"case","label":"United States v. Comstock","cite":"560 U.S. 126","y":2010,"id":"2009/08-1224","sc":1,"sum":"The Court held that the Necessary and Proper Clause granted Congress authority to enact the Adam Walsh Protection and Safety Act.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"United States v. Madigan","cite":"300 U.S. 500","y":1937,"id":"scdb/1936-059","sc":1,"sum":"1. The provisions of § 305 of the World War Veterans' Act, as amended, whereby a policy which has lapsed while the insured was suffering from a compensable disability for which compensation was not collected may be revived and matured, pro tanto, if the insured has become permanently disabled, by applying the uncollected compensation as premiums, do not extend to an earlier policy which was converted into the one …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16"}},{"t":"case","label":"Virginia v. Am. Booksellers Ass’n, Inc.","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"op":7,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Yazoo & Mississippi Valley R.R. Co. v. Thomas","cite":"132 U.S. 174","y":1889,"id":"scdb/1889-025","sc":1,"sum":"This court has jurisdiction to review, on writ of error, a decision of the highest court of a State, in which it is decided that a provision in a tax act of the State that it shall not apply to railroad corporations exempted from taxation by their charters is not applicable to a particular corporation, party to the suit, although its charter contains a provision respecting exemption from taxation.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"44"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"usc","label":"15 U.S.C. § 7807","url":"https://www.law.cornell.edu/uscode/text/15/7807","stext":{"head":"§7807. Sense of Congress","paras":[[0,"It is the sense of Congress that States should enact the Uniform Athlete Agents Act of 2000 drafted by the National Conference of Commissioners on Uniform State Laws, to protect student athletes and the integrity of amateur sports from unscrupulous sports agents. In particular, it is the sense of Congress that States should enact the provisions relating to the registration of sports agents, the required form of contract, the right of the student athlete to cancel an agency contract, the disclosure requirements relating to record maintenance, reporting, renewal, notice, warning, and security, and the provisions for reciprocity among the States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/7807?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7807. Sense of Congress","tname":"Commerce and Trade","by":{"0":"35"}},{"t":"usc","label":"26 U.S.C. § 36B","url":"https://www.law.cornell.edu/uscode/text/26/36B","stext":{"head":"§36B. Refundable credit for coverage under a qualified health plan","paras":[[0,"(a) In general"],[0,"In the case of an applicable taxpayer, there shall be allowed as a credit against the tax imposed by this subtitle for any taxable year an amount equal to the premium assistance credit amount of the taxpayer for the taxable year."],[0,"(b) Premium assistance credit amount"],[0,"For purposes of this section—"],[0,"(1) In general"],[1,"The term \"premium assistance credit amount\" means, with respect to any taxable year, the sum of the premium assistance amounts determined under paragraph (2) with respect to all coverage months of the taxpayer occurring during the taxable year."],[0,"(2) Premium assistance amount"],[1,"The premium assistance amount determined under this subsection with respect to any coverage month is the amount equal to the lesser of—"],[2,"(A) the monthly premiums for such month for 1 or more qualified health plans offered in the individual market within a State which cover the taxpayer, the taxpayer's spouse, or any dependent (as defined in section 152) of the taxpayer and which were enrolled in through an Exchange established by the State under 1311 1 of the Patient Protection and Affordable Care Act, or"],[2,"(B) the excess (if any) of—"],[3,"(i) the adjusted monthly premium for such month for the applicable second lowest cost silver plan with respect to the taxpayer, over"],[3,"(ii) an amount equal to 1/12 of the product of the applicable percentage and the taxpayer's household income for the taxable year."],[0,"(3) Other terms and rules relating to premium assistance amounts"],[1,"For purposes of paragraph (2)—"],[0,"(A) Applicable percentage"],[0,"(i) In general"],[3,"Except as provided in clause (ii), the applicable percentage for any taxable year shall be the percentage such that the applicable percentage for any taxpayer whose household income is within an income tier specified in the following table shall increase, on a sliding scale in a linear manner, from the initial premium percentage to the final premium percentage specified in such table for such income tier:"],[0,"(ii) Indexing"],[0,"(I) In general"],[4,"Subject to subclause (II), in the case of taxable years beginning in any calendar year after 2014, the initial and final applicable percentages under clause (i) (as in effect for the preceding calendar year after application of this clause) shall be adjusted to reflect the excess of the rate of premium growth for the preceding calendar year over the rate of income growth for the preceding calendar year."],[0,"(II) Additional adjustment"],[4,"Except as provided in subclause (III), in the case of any calendar year after 2018, the percentages described in subclause (I) shall, in addition to the adjustment under subclause (I), be adjusted to reflect the excess (if any) of the rate of premium growth estimated under subclause (I) for the preceding calendar year over the rate of growth in the consumer price index for the preceding calendar year."],[0,"(III) Failsafe"],[4,"Subclause (II) shall apply for any calendar year only if the aggregate amount of premium tax credits under this section and cost-sharing reductions under section 1402 of the Patient Protection and Affordable Care Act for the preceding calendar year exceeds an amount equal to 0.504 percent of the gross domestic product for the preceding calendar year."],[0,"(iii) Temporary percentages for 2021 through 2025"],[3,"In the case of a taxable year beginning after December 31, 2020, and before January 1, 2026—"],[4,"(I) clause (ii) shall not apply for purposes of adjusting premium percentages under this subparagraph, and"],[4,"(II) the following table shall be applied in lieu of the table contained in clause (i):"],[0,"(B) Applicable second lowest cost silver plan"],[2,"The applicable second lowest cost silver plan with respect to any applicable taxpayer is the second lowest cost silver plan of the individual market in the rating area in which the taxpayer resides which—"],[3,"(i) is offered through the same Exchange through which the qualified health plans taken into account under paragraph (2)(A) were offered, and"],[3,"(ii) provides—"],[4,"(I) self-only coverage in the case of an applicable taxpayer—"],[5,"(aa) whose tax for the taxable year is determined under section 1(c) 2 (relating to unmarried individuals other than surviving spouses and heads of households) and who is not allowed a deduction under section 151 for the taxable year with respect to a dependent, or"],[5,"(bb) who is not described in item (aa) but who purchases only self-only coverage, and"],[4,"(II) family coverage in the case of any other applicable taxpayer."],[2,"If a taxpayer files a joint return and no credit is allowed under this section with respect to 1 of the spouses by reason of subsection (e), the taxpayer shall be treated as described in clause (ii)(I) unless a deduction is allowed under section 151 for the taxable year with respect to a dependent other than either spouse and subsection (e) does not apply to the dependent."],[0,"(C) Adjusted monthly premium"],[2,"The adjusted monthly premium for an applicable second lowest cost silver plan is the monthly premium which would have been charged (for the rating area with respect to which the premiums under paragraph (2)(A) were determined) for the plan if each individual covered under a qualified health plan taken into account under paragraph (2)(A) were covered by such silver plan and the premium was adjusted only for the age of each such individual in the manner allowed under section 2701 of the Public Health Service Act. In the case of a State participating in the wellness discount demonstration project under section 2705(d) of the Public Health Service Act, the adjusted monthly premium shall be determined without regard to any premium discount or rebate under such project."],[0,"(D) Additional benefits"],[2,"If—"],[3,"(i) a qualified health plan under section 1302(b)(5) of the Patient Protection and Affordable Care Act offers benefits in addition to the essential health benefits required to be provided by the plan, or"],[3,"(ii) a State requires a qualified health plan under section 1311(d)(3)(B) of such Act to cover benefits in addition to the essential health benefits required to be provided by the plan,"],[2,"the portion of the premium for the plan properly allocable (under rules prescribed by the Secretary of Health and Human Services) to such additional benefits shall not be taken into account in determining either the monthly premium or the adjusted monthly premium under paragraph (2)."],[0,"(E) Special rule for pediatric dental coverage"],[2,"For purposes of determining the amount of any monthly premium, if an individual enrolls in both a qualified health plan and a plan described in section 1311(d)(2)(B)(ii)(I) 2 of the Patient Protection and Affordable Care Act for any plan year, the portion of the premium for the plan described in such section that (under regulations prescribed by the Secretary) is properly allocable to pediatric dental benefits which are included in the essential health benefits required to be provided by a qualified health plan under section 1302(b)(1)(J) of such Act shall be treated as a premium payable for a qualified health plan."],[0,"(c) Definition and rules relating to applicable taxpayers, coverage months, and qualified health plan"],[0,"For purposes of this section—"],[0,"(1) Applicable taxpayer"],[0,"(A) In general"],[2,"The term \"applicable taxpayer\" means, with respect to any taxable year, a taxpayer whose household income for the taxable year equals or exceeds 100 percent but does not exceed 400 percent of an amount equal to the poverty line for a family of the size involved."],[0,"(B) Special rule for certain individuals lawfully present in the United States"],[2,"If—"],[3,"(i) a taxpayer has a household income which is not greater than 100 percent of an amount equal to the poverty line for a family of the size involved, and"],[3,"(ii) the taxpayer is an alien lawfully present in the United States, but is not eligible for the medicaid program under title XIX of the Social Security Act by reason of such alien status,"],[2,"the taxpayer shall, for purposes of the credit under this section, be treated as an applicable taxpayer with a household income which is equal to 100 percent of the poverty line for a family of the size involved."],[0,"(C) Married couples must file joint return"],[2,"If the taxpayer is married (within the meaning of section 7703) at the close of the taxable year, the taxpayer shall be treated as an applicable taxpayer only if the taxpayer and the taxpayer's spouse file a joint return for the taxable year."],[0,"(D) Denial of credit to dependents"],[2,"No credit shall be allowed under this section to any individual with respect to whom a deduction under section 151 is allowable to another taxpayer for a taxable year beginning in the calendar year in which such individual's taxable year begins."],[0,"(E) Temporary rule for 2021 through 2025"],[2,"In the case of a taxable year beginning after December 31, 2020, and before January 1, 2026, subparagraph (A) shall be applied without regard to \"but does not exceed 400 percent\"."],[0,"(2) Coverage month"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"The term \"coverage month\" means, with respect to an applicable taxpayer, any month if—"],[3,"(i) as of the first day of such month the taxpayer, the taxpayer's spouse, or any dependent of the taxpayer is covered by a qualified health plan described in subsection (b)(2)(A) that was enrolled in through an Exchange established by the State under section 1311 of the Patient Protection and Affordable Care Act, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/36B?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§36B. Refundable credit for coverage under a qualified health plan","tname":"Internal Revenue Code","by":{"0":"4","1":"4,5"}},{"t":"usc","label":"26 U.S.C. § 4980H","url":"https://www.law.cornell.edu/uscode/text/26/4980H","subs":["(a)"],"stext":{"head":"§4980H. Shared responsibility for employers regarding health coverage","paras":[[0,"(a) Large employers not offering health coverage"],[0,"If—"],[1,"(1) any applicable large employer fails to offer to its full-time employees (and their dependents) the opportunity to enroll in minimum essential coverage under an eligible employer-sponsored plan (as defined in section 5000A(f)(2)) for any month, and"],[1,"(2) at least one full-time employee of the applicable large employer has been certified to the employer under section 1411 of the Patient Protection and Affordable Care Act as having enrolled for such month in a qualified health plan with respect to which an applicable premium tax credit or cost-sharing reduction is allowed or paid with respect to the employee,"],[0,"then there is hereby imposed on the employer an assessable payment equal to the product of the applicable payment amount and the number of individuals employed by the employer as full-time employees during such month."],[0,"(b) Large employers offering coverage with employees who qualify for premium tax credits or cost-sharing reductions"],[0,"(1) In general"],[1,"If—"],[2,"(A) an applicable large employer offers to its full-time employees (and their dependents) the opportunity to enroll in minimum essential coverage under an eligible employer-sponsored plan (as defined in section 5000A(f)(2)) for any month, and"],[2,"(B) 1 or more full-time employees of the applicable large employer has been certified to the employer under section 1411 of the Patient Protection and Affordable Care Act as having enrolled for such month in a qualified health plan with respect to which an applicable premium tax credit or cost-sharing reduction is allowed or paid with respect to the employee,"],[1,"then there is hereby imposed on the employer an assessable payment equal to the product of the number of full-time employees of the applicable large employer described in subparagraph (B) for such month and an amount equal to 1/12 of $3,000."],[0,"(2) Overall limitation"],[1,"The aggregate amount of tax determined under paragraph (1) with respect to all employees of an applicable large employer for any month shall not exceed the product of the applicable payment amount and the number of individuals employed by the employer as full-time employees during such month."],[0,"(c) Definitions and special rules"],[0,"For purposes of this section—"],[0,"(1) Applicable payment amount"],[1,"The term \"applicable payment amount\" means, with respect to any month, 1/12 of $2,000."],[0,"(2) Applicable large employer"],[0,"(A) In general"],[2,"The term \"applicable large employer\" means, with respect to a calendar year, an employer who employed an average of at least 50 full-time employees on business days during the preceding calendar year."],[0,"(B) Exemption for certain employers"],[0,"(i) In general"],[3,"An employer shall not be considered to employ more than 50 full-time employees if—"],[4,"(I) the employer's workforce exceeds 50 full-time employees for 120 days or fewer during the calendar year, and"],[4,"(II) the employees in excess of 50 employed during such 120-day period were seasonal workers."],[0,"(ii) Definition of seasonal workers"],[3,"The term \"seasonal worker\" means a worker who performs labor or services on a seasonal basis as defined by the Secretary of Labor, including workers covered by section 500.20(s)(1) of title 29, Code of Federal Regulations and retail workers employed exclusively during holiday seasons."],[0,"(C) Rules for determining employer size"],[2,"For purposes of this paragraph—"],[0,"(i) Application of aggregation rule for employers"],[3,"All persons treated as a single employer under subsection (b), (c), (m), or (o) of section 414 of the Internal Revenue Code of 1986 shall be treated as 1 employer."],[0,"(ii) Employers not in existence in preceding year"],[3,"In the case of an employer which was not in existence throughout the preceding calendar year, the determination of whether such employer is an applicable large employer shall be based on the average number of employees that it is reasonably expected such employer will employ on business days in the current calendar year."],[0,"(iii) Predecessors"],[3,"Any reference in this subsection to an employer shall include a reference to any predecessor of such employer."],[0,"(D) Application of employer size to assessable penalties"],[0,"(i) In general"],[3,"The number of individuals employed by an applicable large employer as full-time employees during any month shall be reduced by 30 solely for purposes of calculating—"],[4,"(I) the assessable payment under subsection (a), or"],[4,"(II) the overall limitation under subsection (b)(2)."],[0,"(ii) Aggregation"],[3,"In the case of persons treated as 1 employer under subparagraph (C)(i), only 1 reduction under subclause (I) or (II) 1 shall be allowed with respect to such persons and such reduction shall be allocated among such persons ratably on the basis of the number of full-time employees employed by each such person."],[0,"(E) Full-time equivalents treated as full-time employees"],[2,"Solely for purposes of determining whether an employer is an applicable large employer under this paragraph, an employer shall, in addition to the number of full-time employees for any month otherwise determined, include for such month a number of full-time employees determined by dividing the aggregate number of hours of service of employees who are not full-time employees for the month by 120."],[0,"(F) Exemption for health coverage under TRICARE or the Department of Veterans Affairs"],[2,"Solely for purposes of determining whether an employer is an applicable large employer under this paragraph for any month, an individual shall not be taken into account as an employee for such month if such individual has medical coverage for such month under—"],[3,"(i) chapter 55 of title 10, United States Code, including coverage under the TRICARE program, or"],[3,"(ii) under a health care program under chapter 17 or 18 of title 38, United States Code, as determined by the Secretary of Veterans Affairs, in coordination with the Secretary of Health and Human Services and the Secretary."],[0,"(3) Applicable premium tax credit and cost-sharing reduction"],[1,"The term \"applicable premium tax credit and cost-sharing reduction\" means—"],[2,"(A) any premium tax credit allowed under section 36B,"],[2,"(B) any cost-sharing reduction under section 1402 of the Patient Protection and Affordable Care Act, and"],[2,"(C) any advance payment of such credit or reduction under section 1412 of such Act."],[0,"(4) Full-time employee"],[0,"(A) In general"],[2,"The term \"full-time employee\" means, with respect to any month, an employee who is employed on average at least 30 hours of service per week."],[0,"(B) Hours of service"],[2,"The Secretary, in consultation with the Secretary of Labor, shall prescribe such regulations, rules, and guidance as may be necessary to determine the hours of service of an employee, including rules for the application of this paragraph to employees who are not compensated on an hourly basis."],[0,"(5) Inflation adjustment"],[0,"(A) In general"],[2,"In the case of any calendar year after 2014, each of the dollar amounts in subsection (b) and paragraph (1) shall be increased by an amount equal to the product of—"],[3,"(i) such dollar amount, and"],[3,"(ii) the premium adjustment percentage (as defined in section 1302(c)(4) of the Patient Protection and Affordable Care Act) for the calendar year."],[0,"(B) Rounding"],[2,"If the amount of any increase under subparagraph (A) is not a multiple of $10, such increase shall be rounded to the next lowest multiple of $10."],[0,"(6) Other definitions"],[1,"Any term used in this section which is also used in the Patient Protection and Affordable Care Act shall have the same meaning as when used in such Act."],[0,"(7) Tax nondeductible"],[2,"For denial of deduction for the tax imposed by this section, see section 275(a)(6)."],[0,"(d) Administration and procedure"],[0,"(1) In general"],[1,"Any assessable payment provided by this section shall be paid upon notice and demand by the Secretary, and shall be assessed and collected in the same manner as an assessable penalty under subchapter B of chapter 68."],[0,"(2) Time for payment"],[1,"The Secretary may provide for the payment of any assessable payment provided by this section on an annual, monthly, or other periodic basis as the Secretary may prescribe."],[0,"(3) Coordination with credits, etc."],[1,"The Secretary shall prescribe rules, regulations, or guidance for the repayment of any assessable payment (including interest) if such payment is based on the allowance or payment of an applicable premium tax credit or cost-sharing reduction with respect to an employee, such allowance or payment is subsequently disallowed, and the assessable payment would not have been required to be made but for such allowance or payment."],[0,"(4) Time for response"],[1,"The Secretary shall allow an applicable large employer at least 90 days from the date of the first letter which informs the employer of a proposed assessment of the employer shared responsibility payment under this section to respond to the proposed assessment before taking any further action with respect to such proposed assessment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/4980H?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§4980H. Shared responsibility for employers regarding health coverage","tname":"Internal Revenue Code","by":{"0":"48, 4, 31"}},{"t":"usc","label":"26 U.S.C. § 5000A","url":"https://www.law.cornell.edu/uscode/text/26/5000A","stext":{"head":"§5000A. Requirement to maintain minimum essential coverage","paras":[[0,"(a) Requirement to maintain minimum essential coverage"],[0,"An applicable individual shall for each month beginning after 2013 ensure that the individual, and any dependent of the individual who is an applicable individual, is covered under minimum essential coverage for such month."],[0,"(b) Shared responsibility payment"],[0,"(1) In general"],[1,"If a taxpayer who is an applicable individual, or an applicable individual for whom the taxpayer is liable under paragraph (3), fails to meet the requirement of subsection (a) for 1 or more months, then, except as provided in subsection (e), there is hereby imposed on the taxpayer a penalty with respect to such failures in the amount determined under subsection (c)."],[0,"(2) Inclusion with return"],[1,"Any penalty imposed by this section with respect to any month shall be included with a taxpayer's return under chapter 1 for the taxable year which includes such month."],[0,"(3) Payment of penalty"],[1,"If an individual with respect to whom a penalty is imposed by this section for any month—"],[2,"(A) is a dependent (as defined in section 152) of another taxpayer for the other taxpayer's taxable year including such month, such other taxpayer shall be liable for such penalty, or"],[2,"(B) files a joint return for the taxable year including such month, such individual and the spouse of such individual shall be jointly liable for such penalty."],[0,"(c) Amount of penalty"],[0,"(1) In general"],[1,"The amount of the penalty imposed by this section on any taxpayer for any taxable year with respect to failures described in subsection (b)(1) shall be equal to the lesser of—"],[2,"(A) the sum of the monthly penalty amounts determined under paragraph (2) for months in the taxable year during which 1 or more such failures occurred, or"],[2,"(B) an amount equal to the national average premium for qualified health plans which have a bronze level of coverage, provide coverage for the applicable family size involved, and are offered through Exchanges for plan years beginning in the calendar year with or within which the taxable year ends."],[0,"(2) Monthly penalty amounts"],[1,"For purposes of paragraph (1)(A), the monthly penalty amount with respect to any taxpayer for any month during which any failure described in subsection (b)(1) occurred is an amount equal to 1/12 of the greater of the following amounts:"],[0,"(A) Flat dollar amount"],[2,"An amount equal to the lesser of—"],[3,"(i) the sum of the applicable dollar amounts for all individuals with respect to whom such failure occurred during such month, or"],[3,"(ii) 300 percent of the applicable dollar amount (determined without regard to paragraph (3)(C)) for the calendar year with or within which the taxable year ends."],[0,"(B) Percentage of income"],[2,"An amount equal to the following percentage of the excess of the taxpayer's household income for the taxable year over the amount of gross income specified in section 6012(a)(1) with respect to the taxpayer for the taxable year:"],[3,"(i) 1.0 percent for taxable years beginning in 2014."],[3,"(ii) 2.0 percent for taxable years beginning in 2015."],[3,"(iii) Zero percent for taxable years beginning after 2015."],[0,"(3) Applicable dollar amount"],[1,"For purposes of paragraph (1)—"],[0,"(A) In general"],[2,"Except as provided in subparagraphs (B) and (C), the applicable dollar amount is $0."],[0,"(B) Phase in"],[2,"The applicable dollar amount is $95 for 2014 and $325 for 2015."],[0,"(C) Special rule for individuals under age 18"],[2,"If an applicable individual has not attained the age of 18 as of the beginning of a month, the applicable dollar amount with respect to such individual for the month shall be equal to one-half of the applicable dollar amount for the calendar year in which the month occurs."],[0,"(4) Terms relating to income and families"],[1,"For purposes of this section—"],[0,"(A) Family size"],[2,"The family size involved with respect to any taxpayer shall be equal to the number of individuals for whom the taxpayer is allowed a deduction under section 151 (relating to allowance of deduction for personal exemptions) for the taxable year."],[0,"(B) Household income"],[2,"The term \"household income\" means, with respect to any taxpayer for any taxable year, an amount equal to the sum of—"],[3,"(i) the modified adjusted gross income of the taxpayer, plus"],[3,"(ii) the aggregate modified adjusted gross incomes of all other individuals who—"],[4,"(I) were taken into account in determining the taxpayer's family size under paragraph (1), and"],[4,"(II) were required to file a return of tax imposed by section 1 for the taxable year."],[0,"(C) Modified adjusted gross income"],[2,"The term \"modified adjusted gross income\" means adjusted gross income increased by—"],[3,"(i) any amount excluded from gross income under section 911, and"],[3,"(ii) any amount of interest received or accrued by the taxpayer during the taxable year which is exempt from tax."],[0,"(d) Applicable individual"],[0,"For purposes of this section—"],[0,"(1) In general"],[1,"The term \"applicable individual\" means, with respect to any month, an individual other than an individual described in paragraph (2), (3), or (4)."],[0,"(2) Religious exemptions"],[0,"(A) Religious conscience exemptions"],[0,"(i) In general"],[3,"Such term shall not include any individual for any month if such individual has in effect an exemption under section 1311(d)(4)(H) of the Patient Protection and Affordable Care Act which certifies that—"],[4,"(I) such individual is a member of a recognized religious sect or division thereof which is described in section 1402(g)(1), and is adherent of established tenets or teachings of such sect or division as described in such section; or"],[4,"(II) such individual is a member of a religious sect or division thereof which is not described in section 1402(g)(1), who relies solely on a religious method of healing, and for whom the acceptance of medical health services would be inconsistent with the religious beliefs of the individual."],[0,"(ii) Special rules"],[0,"(I) Medical health services defined"],[4,"For purposes of this subparagraph, the term \"medical health services\" does not include routine dental, vision and hearing services, midwifery services, vaccinations, necessary medical services provided to children, services required by law or by a third party, and such other services as the Secretary of Health and Human Services may provide in implementing section 1311(d)(4)(H) of the Patient Protection and Affordable Care Act."],[0,"(II) Attestation required"],[4,"Clause (i)(II) shall apply to an individual for months in a taxable year only if the information provided by the individual under section 1411(b)(5)(A) of such Act includes an attestation that the individual has not received medical health services during the preceding taxable year."],[0,"(B) Health care sharing ministry"],[0,"(i) In general"],[3,"Such term shall not include any individual for any month if such individual is a member of a health care sharing ministry for the month."],[0,"(ii) Health care sharing ministry"],[3,"The term \"health care sharing ministry\" means an organization—"],[4,"(I) which is described in section 501(c)(3) and is exempt from taxation under section 501(a),"],[4,"(II) members of which share a common set of ethical or religious beliefs and share medical expenses among members in accordance with those beliefs and without regard to the State in which a member resides or is employed,"],[4,"(III) members of which retain membership even after they develop a medical condition,"],[4,"(IV) which (or a predecessor of which) has been in existence at all times since December 31, 1999, and medical expenses of its members have been shared continuously and without interruption since at least December 31, 1999, and"],[4,"(V) which conducts an annual audit which is performed by an independent certified public accounting firm in accordance with generally accepted accounting principles and which is made available to the public upon request."],[0,"(3) Individuals not lawfully present"],[1,"Such term shall not include an individual for any month if for the month the individual is not a citizen or national of the United States or an alien lawfully present in the United States."],[0,"(4) Incarcerated individuals"],[1,"Such term shall not include an individual for any month if for the month the individual is incarcerated, other than incarceration pending the disposition of charges."],[0,"(e) Exemptions"],[0,"No penalty shall be imposed under subsection (a) with respect to—"],[0,"(1) Individuals who cannot afford coverage"],[0,"(A) In general"],[2,"Any applicable individual for any month if the applicable individual's required contribution (determined on an annual basis) for coverage for the month exceeds 8 percent of such individual's household income for the taxable year described in section 1412(b)(1)(B) of the Patient Protection and Affordable Care Act. For purposes of applying this subparagraph, the taxpayer's household income shall be increased by any exclusion from gross income for any portion of the required contribution made through a salary reduction arrangement."],[0,"(B) Required contribution"],[2,"For purposes of this paragraph, the term \"required contribution\" means—"],[3,"(i) in the case of an individual eligible to purchase minimum essential coverage consisting of coverage through an eligible-employer-sponsored plan, the portion of the annual premium which would be paid by the individual (without regard to whether paid through salary reduction or otherwise) for self-only coverage, or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/5000A?type=usc&year=mostrecent&link-type=html"},"op":8,"ar":5,"head":"§5000A. Requirement to maintain minimum essential coverage","tname":"Internal Revenue Code","by":{"0":"passim"}},{"t":"usc","label":"26 U.S.C. § 6055","url":"https://www.law.cornell.edu/uscode/text/26/6055","subs":["(a)"],"stext":{"head":"§6055. Reporting of health insurance coverage","paras":[[0,"(a) In general"],[0,"Every person who provides minimum essential coverage to an individual during a calendar year shall, at such time as the Secretary may prescribe, make a return described in subsection (b)."],[0,"(b) Form and manner of return"],[0,"(1) In general"],[1,"A return is described in this subsection if such return—"],[2,"(A) is in such form as the Secretary may prescribe, and"],[2,"(B) contains—"],[3,"(i) the name, address and TIN of the primary insured and the name and TIN of each other individual obtaining coverage under the policy,"],[3,"(ii) the dates during which such individual was covered under minimum essential coverage during the calendar year,"],[3,"(iii) in the case of minimum essential coverage which consists of health insurance coverage, information concerning—"],[4,"(I) whether or not the coverage is a qualified health plan offered through an Exchange established under section 1311 of the Patient Protection and Affordable Care Act, and"],[4,"(II) in the case of a qualified health plan, the amount (if any) of any advance payment under section 1412 of the Patient Protection and Affordable Care Act of any cost-sharing reduction under section 1402 of such Act or of any premium tax credit under section 36B with respect to such coverage, and"],[3,"(iv) such other information as the Secretary may require."],[1,"For purposes of subparagraph (B)(i), in the case of any individual whose name is required to be set forth in a return under subsection (a), if the person required to make a return under such subsection is unable to collect information on the TINs of such individuals, the Secretary may allow the individual's full name and date of birth to be substituted for the name and TIN."],[0,"(2) Information relating to employer-provided coverage"],[1,"If minimum essential coverage provided to an individual under subsection (a) consists of health insurance coverage of a health insurance issuer provided through a group health plan of an employer, a return described in this subsection shall include—"],[2,"(A) the name, address, and employer identification number of the employer maintaining the plan,"],[2,"(B) the portion of the premium (if any) required to be paid by the employer, and"],[2,"(C) if the health insurance coverage is a qualified health plan in the small group market offered through an Exchange, such other information as the Secretary may require for administration of the credit under section 45R (relating to credit for employee health insurance expenses of small employers)."],[0,"(c) Statements to be furnished to individuals with respect to whom information is reported"],[0,"(1) In general"],[1,"Every person required to make a return under subsection (a) shall furnish to each individual whose name is required to be set forth in such return a written statement showing—"],[2,"(A) the name and address of the person required to make such return and the phone number of the information contact for such person, and"],[2,"(B) the information required to be shown on the return with respect to such individual."],[0,"(2) Time for furnishing statements"],[1,"The written statement required under paragraph (1) shall be furnished on or before January 31 of the year following the calendar year for which the return under subsection (a) was required to be made."],[0,"(3) 1 Alternative manner of furnishing statements"],[1,"For purposes of this subsection, any person required to make a return under subsection (a) shall be treated as timely furnishing the written statement required under paragraph (1) if—"],[2,"(A) such person provides clear, conspicuous, and accessible notice (at such time and in such manner as the Secretary may provide) that any individual to whom a statement would otherwise be required to be furnished under paragraph (1) may request a copy of such statement, and"],[2,"(B) such person, on request of any such individual, furnishes a copy of such statement to such individual not later than the later of—"],[3,"(i) January 31 of the year following the calendar year for which the return under subsection (a) was required to be made, or"],[3,"(ii) 30 days after the date of such request."],[0,"(3) 1 Electronic delivery"],[1,"An individual shall be deemed to have consented to receive the statement under this subsection in electronic form if such individual has affirmatively consented at any prior time, to the person required to make such statement, to receive such statement in electronic form. The preceding sentence shall not apply if the individual revokes such consent in writing."],[0,"(d) Coverage provided by governmental units"],[0,"In the case of coverage provided by any governmental unit or any agency or instrumentality thereof, the officer or employee who enters into the agreement to provide such coverage (or the person appropriately designated for purposes of this section) shall make the returns and statements required by this section."],[0,"(e) Minimum essential coverage"],[0,"For purposes of this section, the term \"minimum essential coverage\" has the meaning given such term by section 5000A(f)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6055?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§6055. Reporting of health insurance coverage","tname":"Internal Revenue Code","by":{"0":"30"}},{"t":"usc","label":"26 U.S.C. § 6056","url":"https://www.law.cornell.edu/uscode/text/26/6056","subs":["(a)"],"stext":{"head":"§6056. Certain employers required to report on health insurance coverage","paras":[[0,"(a) In general"],[0,"Every applicable large employer required to meet the requirements of section 4980H with respect to its full-time employees during a calendar year shall, at such time as the Secretary may prescribe, make a return described in subsection (b)."],[0,"(b) Form and manner of return"],[0,"A return is described in this subsection if such return—"],[1,"(1) is in such form as the Secretary may prescribe, and"],[1,"(2) contains—"],[2,"(A) the name, date, and employer identification number of the employer,"],[2,"(B) a certification as to whether the employer offers to its full-time employees (and their dependents) the opportunity to enroll in minimum essential coverage under an eligible employer-sponsored plan (as defined in section 5000A(f)(2)),"],[2,"(C) if the employer certifies that the employer did offer to its full-time employees (and their dependents) the opportunity to so enroll—"],[3,"(i) the length of any waiting period (as defined in section 2701(b)(4) of the Public Health Service Act) with respect to such coverage,"],[3,"(ii) the months during the calendar year for which coverage under the plan was available,"],[3,"(iii) the monthly premium for the lowest cost option in each of the enrollment categories under the plan, and"],[3,"(iv) the employer share of the total allowed costs of benefits provided under the plan,"],[2,"(D) the number of full-time employees for each month during the calendar year,"],[2,"(E) the name, address, and TIN of each full-time employee during the calendar year and the months (if any) during which such employee (and any dependents) were covered under any such health benefits plans, and"],[2,"(F) such other information as the Secretary may require."],[0,"The Secretary shall have the authority to review the accuracy of the information provided under this subsection, including the applicable large employer's share under paragraph (2)(C)(iv)."],[0,"(c) Statements to be furnished to individuals with respect to whom information is reported"],[0,"(1) In general"],[1,"Every person required to make a return under subsection (a) shall furnish to each full-time employee whose name is required to be set forth in such return under subsection (b)(2)(E) a written statement showing—"],[2,"(A) the name and address of the person required to make such return and the phone number of the information contact for such person, and"],[2,"(B) the information required to be shown on the return with respect to such individual."],[0,"(2) Time for furnishing statements"],[1,"The written statement required under paragraph (1) shall be furnished on or before January 31 of the year following the calendar year for which the return under subsection (a) was required to be made."],[0,"(3) 1 Alternative manner of furnishing statements"],[1,"For purposes of this subsection, any person required to make a return under subsection (a) shall be treated as timely furnishing the written statement required under paragraph (1) if—"],[2,"(A) such person provides clear, conspicuous, and accessible notice (at such time and in such manner as the Secretary may provide) that any individual to whom a statement would otherwise be required to be furnished under paragraph (1) may request a copy of such statement, and"],[2,"(B) such person, on request of any such individual, furnishes a copy of such statement to such individual not later than the later of—"],[3,"(i) January 31 of the year following the calendar year for which the return under subsection (a) was required to be made, or"],[3,"(ii) 30 days after the date of such request."],[0,"(3) 1 Electronic delivery"],[1,"An individual shall be deemed to have consented to receive the statement under this subsection in electronic form if such individual has affirmatively consented at any prior time, to the person who is the employer of the individual during the calendar year to which the statement relates, to receive such statement in electronic form. The preceding sentence shall not apply if the individual revokes such consent in writing."],[0,"(d) Coordination with other requirements"],[0,"To the maximum extent feasible, the Secretary may provide that—"],[1,"(1) any return or statement required to be provided under this section may be provided as part of any return or statement required under section 6051 or 6055, and"],[1,"(2) in the case of an applicable large employer offering health insurance coverage of a health insurance issuer, the employer may enter into an agreement with the issuer to include information required under this section with the return and statement required to be provided by the issuer under section 6055."],[0,"(e) Coverage provided by governmental units"],[0,"In the case of any applicable large employer which is a governmental unit or any agency or instrumentality thereof, the person appropriately designated for purposes of this section shall make the returns and statements required by this section."],[0,"(f) Definitions"],[0,"For purposes of this section, any term used in this section which is also used in section 4980H shall have the meaning given such term by section 4980H."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6056?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6056. Certain employers required to report on health insurance coverage","tname":"Internal Revenue Code","by":{"0":"30"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"1","1":"2"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","subs":["(r)"],"by":{"0":"48"}},{"t":"usc","label":"42 U.S.C. § 300gg","url":"https://www.law.cornell.edu/uscode/text/42/300gg","stext":{"head":"§300gg. Fair health insurance premiums","paras":[[0,"(a) 1 Prohibiting discriminatory premium rates"],[0,"(1) In general"],[1,"With respect to the premium rate charged by a health insurance issuer for health insurance coverage offered in the individual or small group market—"],[2,"(A) such rate shall vary with respect to the particular plan or coverage involved only by—"],[3,"(i) whether such plan or coverage covers an individual or family;"],[3,"(ii) rating area, as established in accordance with paragraph (2);"],[3,"(iii) age, except that such rate shall not vary by more than 3 to 1 for adults (consistent with section 300gg–6(c) of this title); and"],[3,"(iv) tobacco use, except that such rate shall not vary by more than 1.5 to 1; and"],[2,"(B) such rate shall not vary with respect to the particular plan or coverage involved by any other factor not described in subparagraph (A)."],[0,"(2) Rating area"],[0,"(A) In general"],[2,"Each State shall establish 1 or more rating areas within that State for purposes of applying the requirements of this subchapter."],[0,"(B) Secretarial review"],[2,"The Secretary shall review the rating areas established by each State under subparagraph (A) to ensure the adequacy of such areas for purposes of carrying out the requirements of this subchapter. If the Secretary determines a State's rating areas are not adequate, or that a State does not establish such areas, the Secretary may establish rating areas for that State."],[0,"(3) Permissible age bands"],[1,"The Secretary, in consultation with the National Association of Insurance Commissioners, shall define the permissible age bands for rating purposes under paragraph (1)(A)(iii)."],[0,"(4) Application of variations based on age or tobacco use"],[1,"With respect to family coverage under a group health plan or health insurance coverage, the rating variations permitted under clauses (iii) and (iv) of paragraph (1)(A) shall be applied based on the portion of the premium that is attributable to each family member covered under the plan or coverage."],[0,"(5) Special rule for large group market"],[1,"If a State permits health insurance issuers that offer coverage in the large group market in the State to offer such coverage through the State Exchange (as provided for under section 18032(f)(2)(B) of this title), the provisions of this subsection shall apply to all coverage offered in such market (other than self-insured group health plans offered in such market) in the State."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/300gg?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§300gg. Fair health insurance premiums","tname":"The Public Health and Welfare","by":{"0":"4"}},{"t":"usc","label":"42 U.S.C. § 300hh-31","url":"https://www.law.cornell.edu/uscode/text/42/300hh-31","by":{"0":"48"}},{"t":"usc","label":"42 U.S.C. § 1396a","url":"https://www.law.cornell.edu/uscode/text/42/1396a","subs":["(a)(10)(A)(i)(VIII)","(e)(14)"],"stext":{"head":"§1396a. State plans for medical assistance","paras":[[0,"(a) Contents"],[0,"A State plan for medical assistance must—"],[1,"(1) provide that it shall be in effect in all political subdivisions of the State, and, if administered by them, be mandatory upon them;"],[1,"(2) provide for financial participation by the State equal to not less than 40 per centum of the non-Federal share of the expenditures under the plan with respect to which payments under section 1396b of this title are authorized by this subchapter; and, effective July 1, 1969, provide for financial participation by the State equal to all of such non-Federal share or provide for distribution of funds from Federal or State sources, for carrying out the State plan, on an equalization or other basis which will assure that the lack of adequate funds from local sources will not result in lowering the amount, duration, scope, or quality of care and services available under the plan;"],[1,"(3) provide for granting an opportunity for a fair hearing before the State agency to any individual whose claim for medical assistance under the plan is denied or is not acted upon with reasonable promptness;"],[1,"(4) provide (A) such methods of administration (including methods relating to the establishment and maintenance of personnel standards on a merit basis, except that the Secretary shall exercise no authority with respect to the selection, tenure of office, and compensation of any individual employed in accordance with such methods, including provision for utilization of professional medical personnel in the administration and, where administered locally, supervision of administration of the plan, and, subject to section 1396b(i) of this title, including a specification that the single State agency described in paragraph (5) will ensure necessary transportation for beneficiaries under the State plan to and from providers and a description of the methods that such agency will use to ensure such transportation) as are found by the Secretary to be necessary for the proper and efficient operation of the plan, (B) for the training and effective use of paid subprofessional staff, with particular emphasis on the full-time or part-time employment of recipients and other persons of low income, as community service aides, in the administration of the plan and for the use of nonpaid or partially paid volunteers in a social service volunteer program in providing services to applicants and recipients and in assisting any advisory committees established by the State agency, (C) that each State or local officer, employee, or independent contractor who is responsible for the expenditure of substantial amounts of funds under the State plan, each individual who formerly was such an officer, employee, or contractor, and each partner of such an officer, employee, or contractor shall be prohibited from committing any act, in relation to any activity under the plan, the commission of which, in connection with any activity concerning the United States Government, by an officer or employee of the United States Government, an individual who was such an officer or employee, or a partner of such an officer or employee is prohibited by section 207 or 208 of title 18, and (D) that each State or local officer, employee, or independent contractor who is responsible for selecting, awarding, or otherwise obtaining items and services under the State plan shall be subject to safeguards against conflicts of interest that are at least as stringent as the safeguards that apply under chapter 21 of title 41 to persons described in section 2102(a)(3) of title 41;"],[1,"(5) either provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan; or provide for the establishment or designation of a single State agency to administer or to supervise the administration of the plan, except that the determination of eligibility for medical assistance under the plan shall be made by the State or local agency administering the State plan approved under subchapter I or XVI (insofar as it relates to the aged) if the State is eligible to participate in the State plan program established under subchapter XVI, or by the agency or agencies administering the supplemental security income program established under subchapter XVI or the State plan approved under part A of subchapter IV if the State is not eligible to participate in the State plan program established under subchapter XVI;"],[1,"(6) provide that the State agency will make such reports, in such form and containing such information, as the Secretary may from time to time require, and comply with such provisions as the Secretary may from time to time find necessary to assure the correctness and verification of such reports;"],[1,"(7) provide—"],[2,"(A) safeguards which restrict the use or disclosure of information concerning applicants and recipients to purposes directly connected with—"],[3,"(i) the administration of the plan; and"],[3,"(ii) the exchange of information necessary to certify or verify the certification of eligibility of children for free or reduced price breakfasts under the Child Nutrition Act of 1966 [42 U.S.C. 1771 et seq.] and free or reduced price lunches under the Richard B. Russell National School Lunch Act [42 U.S.C. 1751 et seq.], in accordance with section 9(b) of that Act [42 U.S.C. 1758(b)], using data standards and formats established by the State agency; and"],[2,"(B) that, notwithstanding the Express Lane option under subsection (e)(13), the State may enter into an agreement with the State agency administering the school lunch program established under the Richard B. Russell National School Lunch Act under which the State shall establish procedures to ensure that—"],[3,"(i) a child receiving medical assistance under the State plan under this subchapter whose family income does not exceed 133 percent of the poverty line (as defined in section 9902(2) of this title, including any revision required by such section), as determined without regard to any expense, block, or other income disregard, applicable to a family of the size involved, may be certified as eligible for free lunches under the Richard B. Russell National School Lunch Act and free breakfasts under the Child Nutrition Act of 1966 without further application; and"],[3,"(ii) the State agencies responsible for administering the State plan under this subchapter, and for carrying out the school lunch program established under the Richard B. Russell National School Lunch Act (42 U.S.C. 1751 et seq.) or the school breakfast program established by section 4 of the Child Nutrition Act of 1966 (42 U.S.C. 1773), cooperate in carrying out paragraphs (3)(F) and (15) of section 9(b) of that Act [42 U.S.C. 1758(b)];"],[1,"(8) provide that all individuals wishing to make application for medical assistance under the plan shall have opportunity to do so, and that such assistance shall be furnished with reasonable promptness to all eligible individuals;"],[1,"(9) provide—"],[2,"(A) that the State health agency, or other appropriate State medical agency (whichever is utilized by the Secretary for the purpose specified in the first sentence of section 1395aa(a) of this title), shall be responsible for establishing and maintaining health standards for private or public institutions in which recipients of medical assistance under the plan may receive care or services,"],[2,"(B) for the establishment or designation of a State authority or authorities which shall be responsible for establishing and maintaining standards, other than those relating to health, for such institutions,"],[2,"(C) that any laboratory services paid for under such plan must be provided by a laboratory which meets the applicable requirements of section 1395x(e)(9) of this title or paragraphs (16) and (17) of section 1395x(s) of this title, or, in the case of a laboratory which is in a rural health clinic, of section 1395x(aa)(2)(G) of this title, and"],[2,"(D) that the State maintain a consumer-oriented website providing useful information to consumers regarding all skilled nursing facilities and all nursing facilities in the State, including for each facility, Form 2567 State inspection reports (or a successor form), complaint investigation reports, the facility's plan of correction, and such other information that the State or the Secretary considers useful in assisting the public to assess the quality of long term care options and the quality of care provided by individual facilities;"],[1,"(10) provide—"],[2,"(A) for making medical assistance available, including at least the care and services listed in paragraphs (1) through (5), (13)(B), (17), (21), (28), (29), and (30) of section 1396d(a) of this title, to—"],[3,"(i) all individuals—"],[4,"(I) who are receiving aid or assistance under any plan of the State approved under subchapter I, X, XIV, or XVI, or part A or part E of subchapter IV (including individuals eligible under this subchapter by reason of section 602(a)(37),1 606(h),1 or 673(b) of this title, or considered by the State to be receiving such aid as authorized under section 682(e)(6)1 of this title),"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1396a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1396a. State plans for medical assistance","tname":"The Public Health and Welfare","by":{"0":"4, 31"}},{"t":"usc","label":"42 U.S.C. § 18031","url":"https://www.law.cornell.edu/uscode/text/42/18031","subs":["(b)(1)"],"by":{"0":"48, 4"}},{"t":"usc","label":"42 U.S.C. § 18091","url":"https://www.law.cornell.edu/uscode/text/42/18091","subs":["(2)(I)"],"stext":{"head":"§18091. Requirement to maintain minimum essential coverage; findings","paras":[[0,"Congress makes the following findings:"],[0,"(1) In general"],[1,"The individual responsibility requirement provided for in this section (in this section referred to as the \"requirement\") is commercial and economic in nature, and substantially affects interstate commerce, as a result of the effects described in paragraph (2)."],[0,"(2) Effects on the national economy and interstate commerce"],[1,"The effects described in this paragraph are the following:"],[2,"(A) The requirement regulates activity that is commercial and economic in nature: economic and financial decisions about how and when health care is paid for, and when health insurance is purchased. In the absence of the requirement, some individuals would make an economic and financial decision to forego health insurance coverage and attempt to self-insure, which increases financial risks to households and medical providers."],[2,"(B) Health insurance and health care services are a significant part of the national economy. National health spending is projected to increase from $2,500,000,000,000, or 17.6 percent of the economy, in 2009 to $4,700,000,000,000 in 2019. Private health insurance spending is projected to be $854,000,000,000 in 2009, and pays for medical supplies, drugs, and equipment that are shipped in interstate commerce. Since most health insurance is sold by national or regional health insurance companies, health insurance is sold in interstate commerce and claims payments flow through interstate commerce."],[2,"(C) The requirement, together with the other provisions of this Act, will add millions of new consumers to the health insurance market, increasing the supply of, and demand for, health care services, and will increase the number and share of Americans who are insured."],[2,"(D) The requirement achieves near-universal coverage by building upon and strengthening the private employer-based health insurance system, which covers 176,000,000 Americans nationwide. In Massachusetts, a similar requirement has strengthened private employer-based coverage: despite the economic downturn, the number of workers offered employer-based coverage has actually increased."],[2,"(E) The economy loses up to $207,000,000,000 a year because of the poorer health and shorter lifespan of the uninsured. By significantly reducing the number of the uninsured, the requirement, together with the other provisions of this Act, will significantly reduce this economic cost."],[2,"(F) The cost of providing uncompensated care to the uninsured was $43,000,000,000 in 2008. To pay for this cost, health care providers pass on the cost to private insurers, which pass on the cost to families. This cost-shifting increases family premiums by on average over $1,000 a year. By significantly reducing the number of the uninsured, the requirement, together with the other provisions of this Act, will lower health insurance premiums."],[2,"(G) 62 percent of all personal bankruptcies are caused in part by medical expenses. By significantly increasing health insurance coverage, the requirement, together with the other provisions of this Act, will improve financial security for families."],[2,"(H) Under the Employee Retirement Income Security Act of 1974 (29 U.S.C. 1001 et seq.), the Public Health Service Act (42 U.S.C. 201 et seq.), and this Act, the Federal Government has a significant role in regulating health insurance. The requirement is an essential part of this larger regulation of economic activity, and the absence of the requirement would undercut Federal regulation of the health insurance market."],[2,"(I) Under sections 2704 and 2705 of the Public Health Service Act [42 U.S.C. 300gg–3, 300gg–4] (as added by section 1201 of this Act), if there were no requirement, many individuals would wait to purchase health insurance until they needed care. By significantly increasing health insurance coverage, the requirement, together with the other provisions of this Act, will minimize this adverse selection and broaden the health insurance risk pool to include healthy individuals, which will lower health insurance premiums. The requirement is essential to creating effective health insurance markets in which improved health insurance products that are guaranteed issue and do not exclude coverage of pre-existing conditions can be sold."],[2,"(J) Administrative costs for private health insurance, which were $90,000,000,000 in 2006, are 26 to 30 percent of premiums in the current individual and small group markets. By significantly increasing health insurance coverage and the size of purchasing pools, which will increase economies of scale, the requirement, together with the other provisions of this Act, will significantly reduce administrative costs and lower health insurance premiums. The requirement is essential to creating effective health insurance markets that do not require underwriting and eliminate its associated administrative costs."],[0,"(3) Supreme Court ruling"],[1,"In United States v. South-Eastern Underwriters Association (322 U.S. 533 (1944)), the Supreme Court of the United States ruled that insurance is interstate commerce subject to Federal regulation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/18091?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§18091. Requirement to maintain minimum essential coverage; findings","tname":"The Public Health and Welfare","by":{"0":"44, 45"}},{"t":"law","label":"Pub. L. No. 100-418","url":"https://www.govinfo.gov/link/statute/102/1107","by":{"0":"36"}},{"t":"law","label":"Pub. L. No. 111-148","url":"https://www.govinfo.gov/link/plaw/111/public/148","by":{"0":"i, 48","1":"41, 42"}},{"t":"law","label":"Pub. L. No. 115-97","url":"https://www.govinfo.gov/link/plaw/115/public/97","by":{"0":"6, 17","1":"10"}},{"t":"const","label":"Article I, Section 8, Clause 18","clauses":[["necessary-proper","Necessary and Proper Clause"]],"text":"To make all Laws which shall be necessary and proper for carrying into Execution the foregoing Powers, and all other Powers vested by this Constitution in the Government of the United States, or in any Department or Officer thereof.","by":{"0":"37"}},{"t":"usc","label":"4 U.S.C. § 8","url":"https://www.law.cornell.edu/uscode/text/4/8","stext":{"head":"§8. Respect for flag","paras":[[0,"No disrespect should be shown to the flag of the United States of America; the flag should not be dipped to any person or thing. Regimental colors, State flags, and organization or institutional flags are to be dipped as a mark of honor."],[0,"(a) The flag should never be displayed with the union down, except as a signal of dire distress in instances of extreme danger to life or property."],[0,"(b) The flag should never touch anything beneath it, such as the ground, the floor, water, or merchandise."],[0,"(c) The flag should never be carried flat or horizontally, but always aloft and free, except as may be necessary in limited circumstances and done in a respectful manner as part of a military or patriotic observance."],[0,"(d) The flag should never be used as wearing apparel, bedding, or drapery. It should never be festooned, drawn back, nor up, in folds, but always allowed to fall free. Bunting of blue, white, and red, always arranged with the blue above, the white in the middle, and the red below, should be used for covering a speaker's desk, draping the front of the platform, and for decoration in general."],[0,"(e) The flag should never be fastened, displayed, used, or stored in such a manner as to permit it to be easily torn, soiled, or damaged in any way."],[0,"(f) The flag should never be used as a covering for a ceiling."],[0,"(g) The flag should never have placed upon it, nor on any part of it, nor attached to it any mark, insignia, letter, word, figure, design, picture, or drawing of any nature."],[0,"(h) The flag should never be used as a receptacle for receiving, holding, carrying, or delivering anything."],[0,"(i) The flag should never be used for advertising purposes in any manner whatsoever. It should not be embroidered on such articles as cushions or handkerchiefs and the like, printed or otherwise impressed on paper napkins or boxes or anything that is designed for temporary use and discard. Advertising signs should not be fastened to a staff or halyard from which the flag is flown."],[0,"(j) No part of the flag should ever be used as a costume or athletic uniform. However, a flag patch may be affixed to the uniform of military personnel, firemen, policemen, and members of patriotic organizations. The flag represents a living country and is itself considered a living thing. Therefore, the lapel flag pin being a replica, should be worn on the left lapel near the heart."],[0,"(k) The flag, when it is in such condition that it is no longer a fitting emblem for display, should be destroyed in a dignified way, preferably by burning."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/4/8?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§8. Respect for flag","tname":"Flag and Seal, Seat of Government, and the States","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 719n","url":"https://www.law.cornell.edu/uscode/text/15/719n","by":{"1":"30"}},{"t":"usc","label":"18 U.S.C. § 1347","url":"https://www.law.cornell.edu/uscode/text/18/1347","subs":["(b)"],"by":{"1":"6"}},{"t":"usc","label":"22 U.S.C. § 7674","url":"https://www.law.cornell.edu/uscode/text/22/7674","by":{"1":"32"}},{"t":"usc","label":"36 U.S.C. § 135","url":"https://www.law.cornell.edu/uscode/text/36/135","subs":["(b)"],"by":{"1":"32"}},{"t":"usc","label":"42 U.S.C. § 254b-2","url":"https://www.law.cornell.edu/uscode/text/42/254b-2","by":{"1":"6"}},{"t":"law","label":"Pub. L. No. 111-152","url":"https://www.govinfo.gov/link/plaw/111/public/152","by":{"1":"34"}},{"t":"law","label":"Pub. L. No. 114-113","url":"https://www.govinfo.gov/link/plaw/114/public/113","by":{"1":"34"}},{"t":"law","label":"Pub. L. No. 115-120","url":"https://www.govinfo.gov/link/plaw/115/public/120","by":{"1":"34"}},{"t":"law","label":"Pub. L. No. 116-94","url":"https://www.govinfo.gov/link/plaw/116/public/94","by":{"1":"34"}},{"t":"reg","label":"45 C.F.R. § 155.420","url":"https://www.ecfr.gov/current/title-45/section-155.420","subs":["(d)(1)(i)"],"by":{"1":"7"}}]};